    report_path = repo_root / "js" / "report.js"

    if not config_path.exists() or not report_path.exists():
        print("ERROR: school 저장소 루트(js/config.js, js/report.js 존재)에서 실행해주세요.")
        sys.exit(1)

    old_config = config_path.read_text(encoding="utf-8")
    old_report = report_path.read_text(encoding="utf-8")

    if old_config == DATA["config_js"]:
        print("SKIP  config.js는 이미 이 패치가 적용되어 있습니다 (변경 없음).")
    else:
        config_path.write_text(DATA["config_js"], encoding="utf-8")
        print(f"OK    수정: {config_path} (SUPA_URL/SUPA_ANON 제거, PB_BASE 추가)")

    if old_report == DATA["report_js"]:
        print("SKIP  report.js는 이미 이 패치가 적용되어 있습니다 (변경 없음).")
    else:
        report_path.write_text(DATA["report_js"], encoding="utf-8")
        print(f"OK    수정: {report_path} (5개 조회 함수 + 저장/조회 함수 PocketBase로 전환)")

    print()
    print("완료. 남은 과제(이번 패치 범위 밖):")
    print("  - desktop.html, dashboard.html도 동일한 SUPA_URL 의존이 있습니다.")
    print("    (school_student_dashboard는 Postgres 뷰라 PocketBase expand로 재구성 필요)")
    print("  - 온보딩/학습일정표 생성 기능은 아직 코드가 없습니다(설계 문서만 있음).")
    print("  - gopang 저장소의 pb_migrations 8개를 l1-hanlim에 실제 반영해야")
    print("    이 패치가 런타임에서 정상 동작합니다 (fix_jeju_university_gopang.py 참고).")

